(7327686, 1144180, 11769, '<td valign="top">love this</td>', 'love this', '2015-03-17 11:35:54.000000', NULL, 1),
(7327687, 1144140, 11769, '<td valign="top">wonderful shot. one of them is staring back at me</td>', 'wonderful shot. one of them is staring back at me', '2015-03-17 11:37:32.000000', NULL, 1),
(7327689, 1144139, 11769, '<td valign="top">though it can seem a long way off, just travel down the road a bit more.</td>', 'though it can seem a long way off, just travel down the road a bit more.', '2015-03-17 11:41:23.000000', NULL, 1),
(7327691, 1144097, 11769, '<td valign="top">love shots from cars</td>', 'love shots from cars', '2015-03-17 11:42:44.000000', NULL, 1),
