(7330750, 1143969, 94815, '<td valign="top">On the spot and in the moment. Good crowd thrusting pattern and emotional faces framed to make the point.</td>', 'On the spot and in the moment. Good crowd thrusting pattern and emotional faces framed to make the point.', '2015-03-19 22:38:10.000000', NULL, 1),
(7330751, 1144146, 94815, '<td valign="top">Frozen as it were, and striking shadows. Perfectly full ranging tones give it real power only slightly diminished by the loose crop, Try giving up some of the right and left excess to compress the movement into the essentials. So nearly so great. It''s a rare favorite for me for what it could be.</td>', 'Frozen as it were, and striking shadows. Perfectly full ranging tones give it real power only slightly diminished by the loose crop, Try giving up some of the right and left excess to compress the movement into the essentials. So nearly so great. It''s a rare favorite for me for what it could be.', '2015-03-19 22:39:38.000000', NULL, 1),
(7330754, 1144128, 94815, '<td valign="top">Strong and disorienting point of view conveying a poignantly self conscious if narcissitic anxiety so nearly impossible for a lesser talent to capture.</td>', 'Strong and disorienting point of view conveying a poignantly self conscious if narcissitic anxiety so nearly impossible for a lesser talent to capture.', '2015-03-19 22:42:39.000000', NULL, 1),
